}
const allowed = ACTIONS[row.kind] || [];
if (allowed.indexOf(a) < 0) return out('Unknown action', '<p>This link does not carry a valid choice.</p>', 'bad');
const sessions = parse(row.sessionsJson, []);
const conflicts = parse(row.conflictsJson, []);
if (a === 'swap' && !conflicts.length) return out('Nothing to swap', '<p>There is no conflict recorded for this event.</p>', 'warn');
const labels = { add: 'Add to calendar', ignore: 'Ignore', keep: 'Keep my schedule', swap: 'Swap to the new event', book: 'Book the meeting', decline: 'Do not book' };
const form = '<form method="post" action="' + CONFIRM_URL + '">'
