  + '<button type="submit">Confirm: ' + esc(labels[a]) + '</button></form>';
return out(labels[a] + '?', describe(row, a, sessions, conflicts) + form + '<p class="m">Nothing has changed yet.</p>', a === 'swap' ? 'warn' : 'ok');

