const req = $('Decision Confirm').first().json;
const b = req.body || {};
const t = String(b.t || '');
const a = String(b.a || '').toLowerCase();
const row = $input.first().json || {};
function bad(title, msg, tone) { return [{ json: { route: 'invalid', html: page(title, '<p>' + msg + '</p>', tone || 'bad') } }]; }
if (!t || !row.token || row.token !== t) return bad('Link not valid', 'This decision link is unknown or no longer valid.');
if (row.status !== 'pending') return bad('Already decided', esc(row.title) + ' was already handled: ' + esc(row.status) + '.', 'warn');
const allowed = ACTIONS[row.kind] || [];
if (allowed.indexOf(a) < 0) return bad('Unknown action', 'This request does not carry a valid choice.');
const sessions = parse(row.sessionsJson, []);
const conflicts = parse(row.conflictsJson, []);
const creates = ['add', 'swap', 'book'].indexOf(a) >= 0;
if (a === 'swap' && !conflicts.length) return bad('Nothing to swap', 'There is no conflict recorded for this event.', 'warn');
if (creates && !sessions.length) return bad('Nothing to schedule', 'This decision has no date to put in the calendar.');
return [{ json: {
  route: creates ? 'create' : 'record', action: a, kind: row.kind, token: t, title: row.title || '',
  link: row.link || '', organizer: row.organizer || '', counterpartEmail: row.counterpartEmail || '',
  threadId: row.threadId || '', summary: row.summary || '', sessions: sessions, conflicts: conflicts,
  calendarId: row.calendarId || '', calendarName: row.calendarName || '',
  newStatus: STATUS[a]
} }];

const d = $('Validate Decision').first().json;
const MEET = 'primary';
return d.sessions.map(function (s, i) {
  const multi = d.sessions.length > 1 ? ' (' + (i + 1) + '/' + d.sessions.length + ')' : '';
  let desc = '';
  if (d.kind === 'event') {
    if (d.link) desc += 'Link: ' + d.link + '\n';
    if (d.organizer) desc += 'Organizer: ' + d.organizer + '\n';
  } else {
    desc += 'Confirmed by ' + (d.counterpartEmail || 'contact') + ' by email.\n';
  }
  if (d.summary) desc += '\n' + d.summary + '\n';
  desc += '\nAdded by Inbox Pilot after your approval.';
  return { json: {
    calendarId: d.calendarId || (d.kind === 'meeting' ? MEET : 'primary'),
    summary: d.title + multi, description: desc,
    location: d.kind === 'event' ? (d.link || '') : '',
    start: s.startISO, end: s.endISO
  } };
});

const items = $input.all();
const ids = items.map(function (it) { return it.json.id; }).filter(Boolean);
const links = items.map(function (it) { return it.json.htmlLink; }).filter(Boolean);
return [{ json: { createdIds: ids.join(','), createdLinks: links, createdCount: ids.length } }];

function readBusy(node) {
  const res = { events: [], ok: true, failed: [], checked: [] };
  let items = [];
  try { items = $(node).all(); } catch (e) { res.ok = false; res.failed.push('busy calendars not read'); return res; }
  if (!items.length) { res.ok = false; res.failed.push('busy calendars returned nothing'); }
  items.forEach(function (it) {
    const e = it.json || {};
    if (e.__summary) { res.checked = e.calendars || []; return; }
    if (e.__calendarError) { res.ok = false; res.failed.push(e.calendarName || e.calendarId); return; }
    if (e.error) { res.ok = false; res.failed.push(String((e.error && e.error.message) || e.error)); return; }
    if (e.start) res.events.push(e);
  });
  return res;
}
const ZONE = 'Europe/Rome';
function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function fmtRange(a, b) { const s = DateTime.fromISO(a).setZone(ZONE); const e = DateTime.fromISO(b).setZone(ZONE); return s.toFormat('ccc d LLL yyyy, HH:mm') + '-' + (s.hasSame(e, 'day') ? e.toFormat('HH:mm') : e.toFormat('ccc d LLL HH:mm')); }

const d = $('Validate Decision').first().json;
if (d.action !== 'swap') return [{ json: { skip: true } }];
const busy = [];
function interval(e) {
  if (e.start && e.start.dateTime) return [DateTime.fromISO(e.start.dateTime), DateTime.fromISO(e.end.dateTime)];
  if (e.start && e.start.date) return [DateTime.fromISO(e.start.date, { zone: ZONE }).startOf('day'), DateTime.fromISO(e.end.date, { zone: ZONE }).startOf('day')];
  return null;
}
readBusy('Get Busy Events').events.forEach(function (e) {
  if (!e || !e.start || e.status === 'cancelled' || e.transparency === 'transparent') return;
  if (e.eventType === 'workingLocation' || e.eventType === 'birthday') return;
  const x = interval(e);
  if (x) busy.push(x);
});
d.sessions.forEach(function (s) { busy.push([DateTime.fromISO(s.startISO), DateTime.fromISO(s.endISO)]); });
function isFree(a, b) { return !busy.some(function (x) { return a < x[1] && b > x[0]; }); }
function findSlots(minutes, n) {
  const found = [];
  const now = DateTime.now().setZone(ZONE);
  for (let k = 1; k <= 21 && found.length < n; k++) {
    const day = now.plus({ days: k }).startOf('day');
    if (day.weekday >= 6) continue;
    for (let m = 9 * 60; m + minutes <= 18 * 60; m += 30) {
      const s = day.plus({ minutes: m });
      const e = s.plus({ minutes: minutes });
      if (isFree(s, e)) { found.push([s, e]); break; }
    }
  }
  return found;
}
const plans = [];
d.conflicts.forEach(function (c) {
  if (c.allDay) return;
  const others = (c.attendees || []).filter(function (a) { return !a.self && a.email && !a.resource; }).map(function (a) { return a.email; });
  const to = c.organizerSelf ? others : (c.organizerEmail ? [c.organizerEmail] : []);
  if (!to.length) return;
  let mins = Math.round(DateTime.fromISO(c.endISO).diff(DateTime.fromISO(c.startISO), 'minutes').minutes);
  if (!(mins > 0)) mins = 60;
  mins = Math.min(mins, 240);
  const slots = findSlots(mins, 3);
  slots.forEach(function (x) { busy.push(x); });
  plans.push({ json: {
    skip: false, to: to.join(', '), conflictSummary: c.summary || '(meeting)',
    conflictWhen: fmtRange(c.startISO, c.endISO), organizerSelf: !!c.organizerSelf,
    slotsText: slots.map(function (x) { return x[0].setZone(ZONE).toFormat('cccc d LLLL, HH:mm') + '-' + x[1].setZone(ZONE).toFormat('HH:mm'); }).join('; ')
  } });
});
if (!plans.length) return [{ json: { skip: true } }];
return plans;

parameters.text:
=Write a short, polite email from Alex Doe asking to move an existing meeting because a conflicting commitment came up.

Meeting: {{ $json.conflictSummary }}
Currently scheduled: {{ $json.conflictWhen }} (Europe/Rome)
{{ $json.organizerSelf ? "Alex organized this meeting; the email goes to the other participants." : "The recipient organized this meeting; Alex asks them to move it." }}
Alternative times Alex is free (Europe/Rome): {{ $json.slotsText || "none found in the next three weeks - ask them to suggest a time" }}

Rules: write in the language of the meeting title; if unclear, Italian. List the alternative times exactly as given. Do not invent times or reasons. Under 120 words. Sign off as Alex.
Respond with ONLY the JSON object required by the schema.

