const plans = $('Plan Follow-ups').all().filter(function (it) { return it.json.skip === false; });
return $input.all().map(function (it, i) {
  const o = it.json.output || {};
  const p = (plans[i] && plans[i].json) || {};
  return { json: { to: p.to, subject: o.subject || ('Reschedule: ' + p.conflictSummary), body: o.body || '' } };
});

