const d = $('Validate Decision').first().json;
let created = { createdCount: 0, createdLinks: [] };
try { created = $('After Create').first().json; } catch (err) { }
let drafts = 0;
try { drafts = $('Create Reschedule Draft').all().filter(function (it) { return it.json && it.json.id; }).length; } catch (err) { drafts = 0; }
const titles = { add: 'Added to your calendar', ignore: 'Ignored', keep: 'Kept your schedule', swap: 'Swapped', book: 'Meeting booked', decline: 'Not booked' };
let html = '<p><b>' + esc(d.title) + '</b></p>';
if (created.createdCount) {
  html += '<p>Calendar: ' + created.createdLinks.map(function (l, i) { return '<a href="' + esc(l) + '">event ' + (i + 1) + '</a>'; }).join(', ') + '</p>';
}
if (d.action === 'swap') {
  html += '<p>' + drafts + ' reschedule draft' + (drafts === 1 ? '' : 's') + ' created in Gmail. Nothing was sent.</p>';
  html += '<p class="m">Your existing events were not deleted. Move or cancel them once the other side agrees.</p>';
}
if (d.action === 'book') html += '<p class="m">Remember to send the confirmation reply waiting in your Drafts.</p>';
if (d.action === 'decline') html += '<p class="m">The proposed slots are free again. Delete the confirmation reply in Drafts if you will not send it.</p>';
return [{ json: { html: page(titles[d.action] || 'Done', html, 'ok') } }];
